#' Plot age schedules of mortality generated by qx()
#'
#' @description Plot the 1qx or 5qx age schedules returned by \code{qx()} on either the natural or the logit scale, and optionally save the plot as a PNG or PDF file.
#' @author Samuel J. Clark, \email{work@samclark.net}
#'
#' @param q Data frame: age schedules returned by \code{qx()}, single-year (ages 0 to 109) or five-year (age groups 0, 1-4, 5-9, ..., 105-109, and 110+ on the natural scale), on either scale. Each column is one schedule.
#' @param outlogit Boolean: plot logit-scale or natural-scale nqx values. Default is FALSE (natural scale). On the logit scale the open age group 110+ is not plotted because logit(1) is not defined.
#' @param file Optional character: the name of a file ending in .png or .pdf to save the plot in, instead of drawing it on the current graphics device. Default is NULL (no file).
#' @param width Decimal: width of the saved plot in inches. Default is 7.
#' @param height Decimal: height of the saved plot in inches. Default is 5.
#' @param main Optional character: the title of the plot. Default is NULL, which gives "SVD-Comp 1qx" or "SVD-Comp 5qx".
#' @param legend Boolean: add a legend with the column labels of q (the input child and adult mortality), top left on the natural scale and bottom right on the logit scale. Default is TRUE.
#' @return Invisibly, a data frame of the plotted values: the starting age of each age group, then one column for each schedule.
#' @examples
#' plotqx(qx("female",c(0.005,0.05,0.2)))
#' plotqx(qx("male",0.03,am=0.26,out5=FALSE),outlogit=TRUE)
#' plotqx(qx("female",0.05),file=file.path(tempdir(),"female-0.05.pdf"))
#' @importFrom graphics legend matplot
#' @importFrom grDevices dev.off hcl pdf png
#' @export
plotqx <- function(q,outlogit=FALSE,file=NULL,width=7,height=5,main=NULL,legend=TRUE) {

  # q: data frame of age schedules from qx(), one column per schedule
  # outlogit: boolean, plot logit(nqx) rather than nqx
  # file: optional .png or .pdf file to save the plot in
  # width, height: size of the saved plot in inches
  # main: title; legend: boolean, add a legend with the column labels

  # ensure the parameters have reasonable values
  if (missing(q))
    stop('<q> (age schedules returned by qx()) must be given')
  labels <- colnames(q)
  q <- as.matrix(q)
  if (!is.numeric(q) | any(is.na(q)))
    stop('<q> must contain numbers only, e.g. the age schedules returned by qx()')
  if (!is.logical(outlogit) || length(outlogit) != 1 || is.na(outlogit))
    stop('<outlogit> must be TRUE or FALSE')
  if (!is.null(file)) {
    if (!is.character(file) || length(file) != 1 || !grepl("\\.(png|pdf)$",file,ignore.case=TRUE))
      stop('<file> must be the name of a file ending in .png or .pdf')
  }
  if (is.null(labels)) {
    labels <- paste("schedule",1:ncol(q))
  }

  # ages: single-year ages 0-109, or the starting ages of the five-year age groups
  # (24 groups on the natural scale; 23 on the logit scale, without 110+)
  if (nrow(q) == 110) {
    ages <- 0:109
    q.name <- "1qx"
  } else if (nrow(q) %in% c(23,24)) {
    ages <- c(0,1,seq(5,110,5))[1:nrow(q)]
    q.name <- "5qx"
  } else {
    stop('<q> must have 110 single-year ages (0 to 109) or 23 or 24 five-year age groups, as returned by qx()')
  }

  # schedules returned on the logit scale (qx(...,outlogit=TRUE)) go back to the natural scale
  if (any(q < 0) | any(q > 1)) {
    q <- expit(q)
  }

  # values to plot: on the logit scale, leave out the open age group 110+ (q = 1)
  if (outlogit) {
    keep <- apply(q < 1,1,all)
    ages <- ages[keep]
    y <- logit(q[keep,,drop=FALSE])
    y.label <- paste("logit(",q.name,")",sep="")
  } else {
    y <- q
    y.label <- q.name
  }
  if (is.null(main)) {
    main <- paste("SVD-Comp",q.name)
  }

  # one color for each schedule
  if (ncol(y) == 1) {
    cols <- "black"
  } else {
    cols <- hcl(h=seq(15,285,length.out=ncol(y)),c=85,l=45)
  }

  # open the file, if there is one, and close it when done
  if (!is.null(file)) {
    if (grepl("\\.png$",file,ignore.case=TRUE)) {
      png(file,width=width,height=height,units="in",res=300)
    } else {
      pdf(file,width=width,height=height)
    }
    on.exit(dev.off(),add=TRUE)
  }

  # plot: lines for single years of age, lines and points for five-year age groups
  matplot(ages,y,type=ifelse(q.name == "1qx","l","o"),lty=1,pch=20,cex=0.6,col=cols
          ,xlab="Age (years)",ylab=y.label,main=main,las=1)
  # legend where the schedules leave space: top left on the natural scale, bottom right on the logit scale
  if (legend) {
    legend(ifelse(outlogit,"bottomright","topleft"),legend=labels,col=cols,lty=1,bty="n",cex=0.8)
  }

  # return the plotted values
  plotted <- data.frame(age=ages,y)
  colnames(plotted) <- c("age",labels)
  rownames(plotted) <- NULL
  return(invisible(plotted))

}
